/**
 * `defineSchedule` — authored at `agent/schedules/<name>.ts`.
 *
 * A schedule starts the agent on a cron cadence instead of waiting for an
 * inbound message. The markdown form is fire-and-forget task mode; the
 * handler form hands work off to a channel (and can call MCP via `args.host.mcp`):
 *
 * ```ts
 * import { defineSchedule } from "@grok/agent-sdk/schedules";
 *
 * export default defineSchedule({
 *   cron: "0 9 * * 1-5",
 *   markdown: "Summarize open incidents and post to the metrics endpoint.",
 * });
 * ```
 *
 * The same fire-and-forget form can be written as a plain markdown file with
 * `cron:` frontmatter (`agent/schedules/<name>.md`).
 */
import { brandDefinition } from "./internal/brand.js";
export function defineSchedule(config) {
    if ((config.markdown === undefined) === (config.run === undefined)) {
        throw new Error("defineSchedule requires exactly one of `markdown` or `run`");
    }
    return brandDefinition("schedule", config);
}
